// Signed amount: refunds count against the total.
function signed(entry) {
	return entry.kind === 'refund' ? -entry.amount : entry.amount;
}
module.exports = { signed };

files.totals.js:
const { signed } = require('./money.js');
function total(entries) {
	let sum = 0;
	for (const e of entries) {
		sum += signed(e);
		if (e.kind === 'refund') sum -= e.amount;
	}
	return sum;
}
module.exports = { total };

